        .menu-link:active .menu-link-lift { transform: translateY(-2px); }
        .menu-link:active .menu-link-fill {
          clip-path: polygon(0 -15%, 118% -15%, 100% 115%, 0 115%);
          -webkit-clip-path: polygon(0 -15%, 118% -15%, 100% 115%, 0 115%);
          transition-duration: 0.2s;
        }
      }
