          height: 100dvh;
          overflow: hidden;

[data-section="foundation"] {
  --fnd-h: clamp(44px, calc(10 * var(--vu)), 180px);
  --fnd-pane: var(--fnd-host-h, 100svh);
  --fnd-u: calc(var(--fnd-pane) / 100);
}
@media (max-width: 900px) and (pointer: coarse) {
  [data-section="foundation"] {
    --fnd-h: clamp(48px, calc(19 * var(--pu)), 80px);
    --fnd-pane: max(100svh, var(--min-h-phone));
    --fnd-u: max(1svh, calc(var(--min-h-phone) / 100));
  }

[data-section="make-a-play"] {
  --play-h: clamp(28px, calc(10 * var(--vu)), 256px);
  --mp-gap: clamp(28px, 3vw, 60px);
  --mp-u: max(1vh, calc(var(--min-h) / 100));
  --mp-min-h: max(min(100svh, calc(var(--page-w) / 1.6)), var(--min-h));
}
[data-section="make-a-play"] [data-mp-frame] { --mp-card-h: var(--mp-h); --mp-card-w: calc(var(--mp-h) * 3 / 4); }
@media (max-width: 767px), (max-width: 900px) and (pointer: coarse) {

[data-footer-invitation]{opacity:0;transition:opacity 800ms var(--ease-editorial)}
[data-footer-invitation="true"]{opacity:1}
@media (prefers-reduced-motion: reduce){
  [data-footer-invitation]{transition:none}
}
@media (max-width: 900px) and (pointer: coarse){
  [data-footer]{--mark-scale:0.55}
  /* Approach smoothing lives in globals.css so all page layers
     share the same footer timing. */
}

